import React, { useEffect, useRef, useState } from "react";
import { Canvas, useFrame } from "@react-three/fiber";

const FIELD_SIZE = 50;
const TILE_SIZE = 1;

// 유저 정보 (예시: 4명)
const USERS = [
  { name: "Red", color: "#e74c3c" },
  { name: "Blue", color: "#3498db" },
  { name: "Green", color: "#27ae60" },
  { name: "Purple", color: "#8e44ad" },
];

// 각 유저의 시작 위치 (네 귀퉁이)
const USER_START_POS = [
  { x: 0, y: 0 }, // 좌상단
  { x: FIELD_SIZE - 1, y: 0 }, // 우상단
  { x: 0, y: FIELD_SIZE - 1 }, // 좌하단
  { x: FIELD_SIZE - 1, y: FIELD_SIZE - 1 }, // 우하단
];

// 특수 타일 종류
const TILE_TYPE = {
  NORMAL: "normal",
  SAND: "sand",
  RIVER: "river",
};

// 필드에 특수 타일 무작위 배치
function generateTileTypes() {
  const arr = Array.from({ length: FIELD_SIZE }, () => Array(FIELD_SIZE).fill(TILE_TYPE.NORMAL));
  // 모래: 10% (노란색), 강: 5% (파랑색)
  for (let x = 0; x < FIELD_SIZE; x++) {
    for (let y = 0; y < FIELD_SIZE; y++) {
      const rand = Math.random();
      if (rand < 0.05) arr[x][y] = TILE_TYPE.RIVER;
      else if (rand < 0.15) arr[x][y] = TILE_TYPE.SAND;
    }
  }
  // 시작 위치는 항상 NORMAL
  USER_START_POS.forEach(pos => {
    arr[pos.x][pos.y] = TILE_TYPE.NORMAL;
  });
  return arr;
}

function Tile({ x, y, userColor, isUser, tileType }) {
  let baseColor = "#e1c699";
  if (tileType === TILE_TYPE.SAND) baseColor = "#f7e08c";
  if (tileType === TILE_TYPE.RIVER) baseColor = "#3498db";
  return (
    <group position={[x * TILE_SIZE, 0, y * TILE_SIZE]}>
      {/* 타일 본체 */}
      <mesh>
        <boxGeometry args={[TILE_SIZE, 0.1, TILE_SIZE]} />
        <meshStandardMaterial color={userColor || baseColor} />
      </mesh>
      {/* 격자선 */}
      <mesh>
        <boxGeometry args={[TILE_SIZE, 0.11, TILE_SIZE]} />
        <meshBasicMaterial color="#222" wireframe transparent opacity={0.5} />
      </mesh>
      {/* 유저 표시 */}
      {isUser && (
        <mesh position={[0, 0.25, 0]}>
          <sphereGeometry args={[0.3, 16, 16]} />
          <meshStandardMaterial color={userColor} />
        </mesh>
      )}
    </group>
  );
}

// 각도(라디안)를 4방향(북, 동, 남, 서) 중 가장 가까운 방향으로 보정
function angleTo4Dir(angle) {
  // 0: 남(아래), -Math.PI/2: 동(오른쪽), Math.PI: 북(위), Math.PI/2: 서(왼쪽)
  const dirs = [
    { dx: 0, dy: 1 },   // 남 (0)
    { dx: 1, dy: 0 },   // 동 (-PI/2)
    { dx: 0, dy: -1 },  // 북 (PI)
    { dx: -1, dy: 0 },  // 서 (PI/2)
  ];
  let idx = Math.round(normalizeAngle(angle) / (Math.PI / 2)) % 4;
  return dirs[idx];
}

function normalizeAngle(angle) {
  let a = angle % (2 * Math.PI);
  if (a < 0) a += 2 * Math.PI;
  return a;
}

const JUMP_DURATION = 400; // 점프 애니메이션 시간(ms)

const Field3D = () => {
  const scriptElement = useRef(null);
  useEffect(() => {
    const script = document.createElement("script");
    script.setAttribute("src", "https://t1.daumcdn.net/kas/static/ba.min.js");
    script.setAttribute("charset", "utf-8");
    script.setAttribute("async", "true");
    scriptElement.current?.appendChild(script);
  }, []);
  // 특수 타일 정보
  const [tileTypes] = useState(() => generateTileTypes());
  // 2차원 배열로 유저별 타일 색상 배정 (상태로 관리)
  const [fieldMap, setFieldMap] = useState(() => {
    const arr = Array.from({ length: FIELD_SIZE }, () => Array(FIELD_SIZE).fill(null));
    USERS.forEach((user, idx) => {
      const pos = USER_START_POS[idx];
      arr[pos.x][pos.y] = user.color;
    });
    return arr;
  });
  // 1번 유저(빨강) 위치 상태
  const [userPos, setUserPos] = useState({ ...USER_START_POS[0] });
  // 이동 딜레이 상태
  const [moveDelay, setMoveDelay] = useState(false);
  // 카메라 각도(라디안, 0: 남쪽, -Math.PI/2: 동쪽, ...)
  const [camAngle, setCamAngle] = useState(0); // 기본 남쪽(아래)
  const [rotateDir, setRotateDir] = useState(0); // -1: 왼쪽, 1: 오른쪽, 0: 정지
  const [isJumping, setIsJumping] = useState(false);
  const [jumpStart, setJumpStart] = useState(null); // {from: {x, y}, to: {x, y}, startTime: number}
  const [jumpY, setJumpY] = useState(0); // 점프 중 y 위치
  const [smoothPos, setSmoothPos] = useState({ x: 0, y: 0 }); // 말의 부드러운 위치

  // 부드러운 연속 회전 (키 누르고 있을 때만)
  useEffect(() => {
    if (rotateDir === 0) return;
    let raf;
    const step = 0.087; // 1초에 5도(0.087 radian)
    function animate() {
      setCamAngle(a => normalizeAngle(a + rotateDir * step));
      raf = requestAnimationFrame(animate);
    }
    animate();
    return () => raf && cancelAnimationFrame(raf);
  }, [rotateDir]);

  // 이동/점프 시 말의 위치를 부드럽게 보간
  useEffect(() => {
    let raf;
    function animate() {
      let target = { x: userPos.x, y: userPos.y };
      if (isJumping && jumpStart) {
        const t = Math.min(1, (Date.now() - jumpStart.startTime) / JUMP_DURATION);
        target = {
          x: jumpStart.from.x + (jumpStart.to.x - jumpStart.from.x) * t,
          y: jumpStart.from.y + (jumpStart.to.y - jumpStart.from.y) * t,
        };
      }
      setSmoothPos(prev => {
        const alpha = 0.3;
        return {
          x: prev.x * (1 - alpha) + target.x * alpha,
          y: prev.y * (1 - alpha) + target.y * alpha,
        };
      });
      raf = requestAnimationFrame(animate);
    }
    animate();
    return () => raf && cancelAnimationFrame(raf);
  }, [userPos, isJumping, jumpStart]);

  // 점프 애니메이션 (jumpY)
  useEffect(() => {
    if (!jumpStart) return;
    let raf;
    function animate() {
      const now = Date.now();
      const t = Math.min(1, (now - jumpStart.startTime) / JUMP_DURATION);
      setJumpY(-4 * Math.pow(t - 0.5, 2) + 1);
      if (t < 1) {
        raf = requestAnimationFrame(animate);
      } else {
        setJumpY(0);
        setJumpStart(null);
        setIsJumping(false);
      }
    }
    animate();
    return () => raf && cancelAnimationFrame(raf);
  }, [jumpStart]);

  // 키보드 이동/회전 처리
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (moveDelay) return;
      // a, ㅁ: 왼쪽 회전 시작
      if ((e.key === "a" || e.key === "A" || e.key === "ㅁ") && rotateDir !== -1) {
        setRotateDir(-1);
        return;
      }
      // d, ㅇ: 오른쪽 회전 시작
      if ((e.key === "d" || e.key === "D" || e.key === "ㅇ") && rotateDir !== 1) {
        setRotateDir(1);
        return;
      }
      // 앞으로 이동(방향키 위 또는 W)
      if (e.key === "ArrowUp" || e.key === "w" || e.key === "W") {
        const dir = angleTo4Dir(camAngle);
        const nx = Math.max(0, Math.min(FIELD_SIZE - 1, userPos.x + dir.dx));
        const ny = Math.max(0, Math.min(FIELD_SIZE - 1, userPos.y + dir.dy));
        if (nx !== userPos.x || ny !== userPos.y) {
          setUserPos({ x: nx, y: ny });
          setFieldMap(prev => {
            const next = prev.map(row => [...row]);
            next[nx][ny] = USERS[0].color;
            return next;
          });
          // 특수 타일 효과
          const type = tileTypes[nx][ny];
          if (type === TILE_TYPE.SAND) {
            setMoveDelay(true);
            setTimeout(() => setMoveDelay(false), 500);
          } else if (type === TILE_TYPE.RIVER) {
            setMoveDelay(true);
            setTimeout(() => setMoveDelay(false), 3000);
          }
        }
        return;
      }
      // 왼쪽 이동(방향키 ← 또는 s)
      if (e.key === "ArrowLeft" || e.key === "s" || e.key === "S") {
        const leftAngle = normalizeAngle(camAngle + Math.PI / 2);
        const dir = angleTo4Dir(leftAngle);
        const nx = Math.max(0, Math.min(FIELD_SIZE - 1, userPos.x + dir.dx));
        const ny = Math.max(0, Math.min(FIELD_SIZE - 1, userPos.y + dir.dy));
        if (nx !== userPos.x || ny !== userPos.y) {
          setUserPos({ x: nx, y: ny });
          setFieldMap(prev => {
            const next = prev.map(row => [...row]);
            next[nx][ny] = USERS[0].color;
            return next;
          });
          // 특수 타일 효과
          const type = tileTypes[nx][ny];
          if (type === TILE_TYPE.SAND) {
            setMoveDelay(true);
            setTimeout(() => setMoveDelay(false), 500);
          } else if (type === TILE_TYPE.RIVER) {
            setMoveDelay(true);
            setTimeout(() => setMoveDelay(false), 3000);
          }
        }
        return;
      }
      // 오른쪽 이동(방향키 → 또는 f)
      if (e.key === "ArrowRight" || e.key === "f" || e.key === "F") {
        const rightAngle = normalizeAngle(camAngle - Math.PI / 2);
        const dir = angleTo4Dir(rightAngle);
        const nx = Math.max(0, Math.min(FIELD_SIZE - 1, userPos.x + dir.dx));
        const ny = Math.max(0, Math.min(FIELD_SIZE - 1, userPos.y + dir.dy));
        if (nx !== userPos.x || ny !== userPos.y) {
          setUserPos({ x: nx, y: ny });
          setFieldMap(prev => {
            const next = prev.map(row => [...row]);
            next[nx][ny] = USERS[0].color;
            return next;
          });
          // 특수 타일 효과
          const type = tileTypes[nx][ny];
          if (type === TILE_TYPE.SAND) {
            setMoveDelay(true);
            setTimeout(() => setMoveDelay(false), 500);
          } else if (type === TILE_TYPE.RIVER) {
            setMoveDelay(true);
            setTimeout(() => setMoveDelay(false), 3000);
          }
        }
        return;
      }
      // 스페이스: 점프(2칸 이동, 중간 칸은 점유하지 않음)
      if (e.code === "Space" || e.key === " ") {
        const dir = angleTo4Dir(camAngle);
        const nx = Math.max(0, Math.min(FIELD_SIZE - 1, userPos.x + dir.dx * 2));
        const ny = Math.max(0, Math.min(FIELD_SIZE - 1, userPos.y + dir.dy * 2));
        if (nx !== userPos.x || ny !== userPos.y) {
          setIsJumping(true);
          setJumpStart({ from: { ...userPos }, to: { x: nx, y: ny }, startTime: Date.now() });
          setUserPos({ x: nx, y: ny });
          setFieldMap(prev => {
            const next = prev.map(row => [...row]);
            next[nx][ny] = USERS[0].color;
            return next;
          });
          // 특수 타일 효과(착지 칸만 적용)
          const type = tileTypes[nx][ny];
          if (type === TILE_TYPE.SAND) {
            setMoveDelay(true);
            setTimeout(() => setMoveDelay(false), 500);
          } else if (type === TILE_TYPE.RIVER) {
            setMoveDelay(true);
            setTimeout(() => setMoveDelay(false), 3000);
          }
        }
        return;
      }
    };
    const handleKeyUp = (e) => {
      // a, ㅁ: 왼쪽 회전 정지
      if (e.key === "a" || e.key === "A" || e.key === "ㅁ") {
        if (rotateDir === -1) setRotateDir(0);
      }
      // d, ㅇ: 오른쪽 회전 정지
      if (e.key === "d" || e.key === "D" || e.key === "ㅇ") {
        if (rotateDir === 1) setRotateDir(0);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
    };
  }, [userPos, moveDelay, tileTypes, camAngle, rotateDir]);

  // 점유율 계산
  const ownership = React.useMemo(() => {
    const counts = USERS.map(() => 0);
    for (let x = 0; x < FIELD_SIZE; x++) {
      for (let y = 0; y < FIELD_SIZE; y++) {
        USERS.forEach((user, idx) => {
          if (fieldMap[x][y] === user.color) counts[idx]++;
        });
      }
    }
    return counts;
  }, [fieldMap]);

  return (
    <div style={{ width: "100vw", height: "100vh", background: "#eaf7e1" }}>
      {/* 점유율 UI */}
      <div style={{
        position: "absolute", top: 16, left: 0, width: "100%", zIndex: 10,
        display: "flex", justifyContent: "center", gap: 32, fontWeight: "bold", fontSize: 18
      }}>
        {USERS.map((user, idx) => (
          <span key={user.name} style={{ color: user.color, textShadow: "1px 1px 2px #fff" }}>
            {user.name}: {ownership[idx]}
          </span>
        ))}
      </div>
      <Canvas shadows>
        <ambientLight intensity={0.6} />
        <directionalLight position={[30, 50, 30]} intensity={0.7} castShadow />
        {/* 50x50 타일 렌더링 */}
        {Array.from({ length: FIELD_SIZE }).map((_, x) =>
          Array.from({ length: FIELD_SIZE }).map((_, y) => (
            <Tile
              key={`${x}-${y}`}
              x={x - FIELD_SIZE / 2}
              y={y - FIELD_SIZE / 2}
              userColor={fieldMap[x][y]}
              tileType={tileTypes[x][y]}
            />
          ))
        )}
        <UserMesh smoothPos={smoothPos} camAngle={camAngle} jumpY={jumpY} />
        <FollowCamera smoothPos={smoothPos} camAngle={camAngle} jumpY={jumpY} />
      </Canvas>

      <div style={{ marginTop: 32, textAlign: "center", 
        position: "fixed",
        left: 0,
        bottom: 0,
        width: "100%", }} ref={scriptElement}>
          <ins
            className="kakao_ad_area"
            style={{ display: "none" }}
            data-ad-unit="DAN-hsPJu5SU6nUfFFLZ"
            data-ad-width="320"
            data-ad-height="50"
          ></ins>
        </div>
    </div>
  );
};

function UserMesh({ smoothPos, camAngle, jumpY }) {
  const ux = smoothPos.x * TILE_SIZE - FIELD_SIZE / 2 * TILE_SIZE + TILE_SIZE / 2;
  const uz = smoothPos.y * TILE_SIZE - FIELD_SIZE / 2 * TILE_SIZE + TILE_SIZE / 2;
  return (
    <group position={[ux, 0.25 + jumpY, uz]} rotation={[0, -camAngle, 0]}>
      <mesh>
        <sphereGeometry args={[0.3, 16, 16]} />
        <meshStandardMaterial color={USERS[0].color} />
      </mesh>
    </group>
  );
}

function FollowCamera({ smoothPos, camAngle, jumpY }) {
  useFrame(({ camera }) => {
    const camHeight = 1.2 + jumpY * 0.7; // 점프 중 카메라도 살짝 위로
    const camBack = 2.0;
    const camAhead = 1.5;
    const ux = smoothPos.x * TILE_SIZE - FIELD_SIZE / 2 * TILE_SIZE + TILE_SIZE / 2;
    const uz = smoothPos.y * TILE_SIZE - FIELD_SIZE / 2 * TILE_SIZE + TILE_SIZE / 2;
    const dx = Math.sin(camAngle);
    const dz = Math.cos(camAngle);
    const cx = ux - dx * camBack;
    const cz = uz - dz * camBack;
    camera.position.set(cx, camHeight, cz);
    const lookX = ux + dx * camAhead;
    const lookZ = uz + dz * camAhead;
    camera.lookAt(lookX, 0.2 + jumpY * 0.7, lookZ);
  });
  return null;
}

export default Field3D;
