import React, { useState, useEffect, useRef } from 'react';
import { 
  Container, 
  Paper, 
  Typography, 
  Button, 
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Box,
  List,
  Card,
  CardContent,
  Divider,
  CircularProgress
} from '@mui/material';
import { format } from 'date-fns';

const CATEGORY_LIST = [
  { code: 'FD6', label: '음식점' },
  { code: 'CE7', label: '카페' }
];

const DEFAULT_IMG = 'https://cdn-icons-png.flaticon.com/512/3075/3075977.png'; // 기본 식당 이미지

const EatSomething = () => {
  const mapRef = useRef(null);
  const [map, setMap] = useState(null);
  const [selectedPlace, setSelectedPlace] = useState(null);
  const [openDialog, setOpenDialog] = useState(false);
  const [searchResults, setSearchResults] = useState([]);
  const [markers, setMarkers] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [category, setCategory] = useState('FD6');
  const [meetingDetails, setMeetingDetails] = useState({
    maxParticipants: 4,
    meetingDate: '',
    meetingTime: '',
    deadline: '',
    description: '',
    restaurantName: '',
    address: '',
    placeId: ''
  });
  const cardRefs = useRef({});
  const listContainerRef = useRef(null);
  const [detailPopup, setDetailPopup] = useState({ open: false, url: '' });

  useEffect(() => {
    if (window.kakao && window.kakao.maps) {
      const options = {
        center: new window.kakao.maps.LatLng(37.5665, 126.9780),
        level: 3
      };
      
      const mapInstance = new window.kakao.maps.Map(mapRef.current, options);
      setMap(mapInstance);

      window.kakao.maps.event.addListener(mapInstance, 'dragend', () => {
        searchPlacesInBounds(category);
      });
      window.kakao.maps.event.addListener(mapInstance, 'zoom_changed', () => {
        searchPlacesInBounds(category);
      });
      searchPlacesInBounds(category);
    }
    // eslint-disable-next-line
  }, []);

  useEffect(() => {
    if (map) {
      searchPlacesInBounds(category);
    }
    // eslint-disable-next-line
  }, [category]);

  // 선택된 식당이 바뀔 때 리스트에서 해당 카드로 스크롤
  useEffect(() => {
    if (selectedPlace && meetingDetails.placeId && cardRefs.current[meetingDetails.placeId]) {
      const node = cardRefs.current[meetingDetails.placeId];
      if (node && listContainerRef.current) {
        node.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }
  }, [selectedPlace, meetingDetails.placeId]);

  const searchPlacesInBounds = (cat) => {
    if (!map) return;
    setIsLoading(true);
    markers.forEach(marker => marker.setMap(null));
    setMarkers([]);
    setSearchResults([]);
    const bounds = map.getBounds();
    const places = new window.kakao.maps.services.Places();
    places.categorySearch(cat, (results, status) => {
      let allMarkers = [];
      if (status === window.kakao.maps.services.Status.OK) {
        allMarkers = results.map(place => {
          const marker = new window.kakao.maps.Marker({
            position: new window.kakao.maps.LatLng(place.y, place.x),
            map: map
          });
          window.kakao.maps.event.addListener(marker, 'click', () => {
            selectPlace(place);
          });
          return marker;
        });
        setMarkers(allMarkers);
        setSearchResults(results);
      } else {
        setMarkers([]);
        setSearchResults([]);
      }
      setIsLoading(false);
    }, { bounds });
  };

  const selectPlace = (place) => {
    if (selectedPlace) {
      selectedPlace.setMap(null);
    }
    const marker = new window.kakao.maps.Marker({
      position: new window.kakao.maps.LatLng(place.y, place.x)
    });
    marker.setMap(map);
    setSelectedPlace(marker);
    setMeetingDetails(prev => ({
      ...prev,
      restaurantName: place.place_name,
      address: place.address_name,
      placeId: place.id
    }));
    map.setCenter(new window.kakao.maps.LatLng(place.y, place.x));
  };

  const handleCreateMeeting = () => {
    // TODO: Firebase에 모임 정보 저장
    setOpenDialog(false);
  };

  const handleDetailOpen = (url) => {
    setDetailPopup({ open: true, url });
  };

  const handleDetailClose = () => {
    setDetailPopup({ open: false, url: '' });
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4 }}>
      <Typography variant="h4" gutterBottom>
        같이 밥 먹을 사람 구하기
      </Typography>

      {/* 카테고리 버튼 */}
      <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
        {CATEGORY_LIST.map((cat) => (
          <Button
            key={cat.code}
            variant={category === cat.code ? 'contained' : 'outlined'}
            onClick={() => setCategory(cat.code)}
          >
            {cat.label}
          </Button>
        ))}
      </Box>

      <Box sx={{ display: 'flex', gap: 2 }}>
        <Box
          ref={mapRef}
          sx={{
            width: '70%',
            height: '500px',
            mb: 2
          }}
        />

        <Paper sx={{ width: '30%', height: '500px', overflow: 'auto', p: 2 }} ref={listContainerRef}>
          <Typography variant="h6" gutterBottom>
            주변 {CATEGORY_LIST.find(c => c.code === category)?.label} 목록
          </Typography>
          {isLoading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', mt: 2 }}>
              <CircularProgress />
            </Box>
          ) : (
            <List>
              {searchResults.map((place, index) => (
                <Card
                  key={place.id}
                  ref={el => cardRefs.current[place.id] = el}
                  sx={{ mb: 2, cursor: 'pointer', border: (selectedPlace && meetingDetails.placeId === place.id) ? '2px solid #1976d2' : '1px solid #eee', display: 'flex', alignItems: 'center' }}
                  onClick={() => selectPlace(place)}
                >
                  <CardContent sx={{ flex: 1, p: 1 }}>
                    <Typography variant="h6">{place.place_name}</Typography>
                    <Typography variant="body2" color="text.secondary">{place.category_name}</Typography>
                    <Typography variant="body2">{place.address_name}</Typography>
                    <Button
                      onClick={e => { e.stopPropagation(); handleDetailOpen(place.place_url); }}
                      size="small"
                      sx={{ mt: 1 }}
                    >
                      상세보기
                    </Button>
                  </CardContent>
                </Card>
              ))}
            </List>
          )}
        </Paper>
      </Box>

      {/* 상세보기 팝업 */}
      <Dialog open={detailPopup.open} onClose={handleDetailClose} maxWidth="md" fullWidth>
        <DialogTitle>상세 정보</DialogTitle>
        <DialogContent sx={{ p: 0 }}>
          <iframe
            src={detailPopup.url}
            title="상세 정보"
            width="100%"
            height="600px"
            style={{ border: 'none' }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleDetailClose}>닫기</Button>
        </DialogActions>
      </Dialog>

      <Button 
        variant="contained" 
        color="primary" 
        onClick={() => setOpenDialog(true)}
        sx={{ mt: 2 }}
        disabled={!selectedPlace}
      >
        모임 만들기
      </Button>

      <Dialog open={openDialog} onClose={() => setOpenDialog(false)}>
        <DialogTitle>새로운 모임 만들기</DialogTitle>
        <DialogContent>
          <TextField
            margin="dense"
            label="식당 이름"
            fullWidth
            value={meetingDetails.restaurantName}
            disabled
          />
          <TextField
            margin="dense"
            label="주소"
            fullWidth
            value={meetingDetails.address}
            disabled
          />
          <TextField
            margin="dense"
            label="최대 참가 인원"
            type="number"
            fullWidth
            value={meetingDetails.maxParticipants}
            onChange={(e) => setMeetingDetails({
              ...meetingDetails,
              maxParticipants: e.target.value
            })}
          />
          <TextField
            margin="dense"
            label="모임 날짜"
            type="date"
            fullWidth
            InputLabelProps={{ shrink: true }}
            value={meetingDetails.meetingDate}
            onChange={(e) => setMeetingDetails({
              ...meetingDetails,
              meetingDate: e.target.value
            })}
          />
          <TextField
            margin="dense"
            label="모임 시간"
            type="time"
            fullWidth
            InputLabelProps={{ shrink: true }}
            value={meetingDetails.meetingTime}
            onChange={(e) => setMeetingDetails({
              ...meetingDetails,
              meetingTime: e.target.value
            })}
          />
          <TextField
            margin="dense"
            label="모집 마감 시간"
            type="time"
            fullWidth
            InputLabelProps={{ shrink: true }}
            value={meetingDetails.deadline}
            onChange={(e) => setMeetingDetails({
              ...meetingDetails,
              deadline: e.target.value
            })}
          />
          <TextField
            margin="dense"
            label="모임 설명"
            multiline
            rows={4}
            fullWidth
            value={meetingDetails.description}
            onChange={(e) => setMeetingDetails({
              ...meetingDetails,
              description: e.target.value
            })}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)}>취소</Button>
          <Button onClick={handleCreateMeeting} variant="contained" color="primary">
            모임 만들기
          </Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
};

export default EatSomething;
