import React, { useState, useEffect, useRef } from "react";

const DEFAULT_ROWS = 10;
const DEFAULT_COLS = 10;
const GAME_TIME = 60; // 60초


// 1~9 중 랜덤 숫자 반환
function getRandomApple() {
  return Math.floor(Math.random() * 9) + 1;
}

// 2차원 배열 생성 함수
function generateRandomBoard(rows, cols) {
  return Array.from({ length: rows }, () =>
    Array.from({ length: cols }, () => getRandomApple())
  );
}

// 합이 10이 되는 사각형 영역이 존재하는지 확인
function checkNoAnswer(board) {
  const BOARD_ROWS = board.length;
  const BOARD_COLS = board[0].length;
  for (let r1 = 0; r1 < BOARD_ROWS; r1++) {
    for (let c1 = 0; c1 < BOARD_COLS; c1++) {
      if (board[r1][c1] === 0) continue;
      for (let r2 = r1; r2 < BOARD_ROWS; r2++) {
        for (let c2 = c1; c2 < BOARD_COLS; c2++) {
          let sum = 0;
          let hasZero = false;
          for (let rr = r1; rr <= r2; rr++) {
            for (let cc = c1; cc <= c2; cc++) {
              if (board[rr][cc] === 0) hasZero = true;
              sum += board[rr][cc];
            }
          }
          if (!hasZero && sum === 10) {
            return false;
          }
        }
      }
    }
  }
  return true;
}

const AppleBoard = () => {
  const [rows, setRows] = useState(DEFAULT_ROWS);
  const [cols, setCols] = useState(DEFAULT_COLS);
  const [customTime, setCustomTime] = useState(GAME_TIME);
  const [board, setBoard] = useState(generateRandomBoard(DEFAULT_ROWS, DEFAULT_COLS));
  const [dragStart, setDragStart] = useState(null);
  const [dragEnd, setDragEnd] = useState(null);
  const [selectedCells, setSelectedCells] = useState([]);
  const [sum, setSum] = useState(0);
  const [score, setScore] = useState(0);
  const [timer, setTimer] = useState(GAME_TIME);
  const [gameOver, setGameOver] = useState(false);
  const intervalRef = useRef(null);
  const scriptElement = useRef(null);



useEffect(() => {
    const script = document.createElement("script");
    script.setAttribute("src", "https://t1.daumcdn.net/kas/static/ba.min.js");
    script.setAttribute("charset", "utf-8");
    script.setAttribute("async", "true");
    scriptElement.current?.appendChild(script);
  }, [board, gameOver]);
  
  // 타이머 시작 및 종료 처리
  useEffect(() => {
    if (gameOver) return;
    setTimer(customTime);
    if (intervalRef.current) clearInterval(intervalRef.current);
    intervalRef.current = setInterval(() => {
      setTimer(prev => {
        if (prev <= 1) {
          clearInterval(intervalRef.current);
          setGameOver(true);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(intervalRef.current);
  }, [rows, cols, customTime, gameOver]);

  // 게임 종료 시 점수 팝업
  useEffect(() => {
    if (gameOver) {
      setTimeout(() => {
        alert(`게임 종료!\n최종 점수: ${(10 * score) + score}`);
      }, 100);
    }
  }, [gameOver, score]);

  // 보드 크기/타이머 변경 시 보드 재생성
  const handleResize = (newRows, newCols) => {
    setRows(newRows);
    setCols(newCols);
    setBoard(generateRandomBoard(newRows, newCols));
    setScore(0);
    setSelectedCells([]);
    setSum(0);
    setGameOver(false);
    setTimer(customTime);
  };

  // 타이머 입력 변경 핸들러
  const handleTimeChange = (e) => {
    let value = parseInt(e.target.value, 10);
    if (isNaN(value) || value < 5) value = 5;
    if (value > 600) value = 600;
    setCustomTime(value);
    setTimer(value);
    setBoard(generateRandomBoard(rows, cols));
    setScore(0);
    setSelectedCells([]);
    setSum(0);
    setGameOver(false);
  };

  // 드래그 시작
  const handleMouseDown = (row, col) => {
    if (gameOver) return;
    setDragStart({ row, col });
    setDragEnd({ row, col });
    setSelectedCells([{ row, col }]);
    setSum(board[row][col]);
  };

  // 드래그 중
  const handleMouseEnter = (row, col) => {
    if (!dragStart || gameOver) return;
    setDragEnd({ row, col });
    const minRow = Math.min(dragStart.row, row);
    const maxRow = Math.max(dragStart.row, row);
    const minCol = Math.min(dragStart.col, col);
    const maxCol = Math.max(dragStart.col, col);
    let cells = [];
    let total = 0;
    for (let r = minRow; r <= maxRow; r++) {
      for (let c = minCol; c <= maxCol; c++) {
        cells.push({ row: r, col: c });
        total += board[r][c];
      }
    }
    setSelectedCells(cells);
    setSum(total);
  };

  // 드래그 끝
  const handleMouseUp = () => {
    if (gameOver) return;
    if (sum === 10 && selectedCells.length > 0) {
        // 정답이라면
      setBoard(prev => {
        const newBoard = prev.map(row => [...row]);
        selectedCells.forEach(cell => {
          newBoard[cell.row][cell.col] = 0;
        });
        setTimeout(() => {
          if (checkNoAnswer(newBoard)) {
            setBoard(generateRandomBoard(rows, cols));
          }
        }, 200);
        return newBoard;
      });
      setScore(prev => prev + 1);
    }
    setDragStart(null);
    setDragEnd(null);
    setSelectedCells([]);
    setSum(0);
  };

  // 셀 하이라이트 여부
  const isSelected = (row, col) =>
    selectedCells.some(cell => cell.row === row && cell.col === col);

  return (
    <>
      <div style={{ display: "flex", alignItems: "flex-start" }}>
        <div style={{ display: "inline-block", background: "#eaffea", padding: 20, userSelect: "none", minWidth: 420 }}>
          <div style={{ marginBottom: 6, fontWeight: "bold", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span>점수: {score}</span>
            <span style={{ color: timer <= 10 ? "#e74c3c" : "#222", fontWeight: "bold", fontSize: 18 }}>⏰ {timer}s</span>
          </div>
          <div style={{ marginBottom: 10, fontWeight: "bold" }}>합계: {sum}</div>
          {board.map((row, rowIdx) => (
            <div key={rowIdx} style={{ display: "flex" }}>
              {row.map((apple, colIdx) => (
                <div
                  key={colIdx}
                  style={{
                    width: 36,
                    height: 36,
                    margin: 2,
                    borderRadius: "50%",
                    background: apple === 0 ? (isSelected(rowIdx, colIdx) ? "#ffeaa7" : "#ecf0f1") : isSelected(rowIdx, colIdx) ? "#f39c12" : "#e74c3c",
                    color: apple === 0 ? "#bbb" : "#fff",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontWeight: "bold",
                    fontSize: 20,
                    boxShadow: "0 1px 2px #aaa",
                    cursor: gameOver ? "default" : "pointer",
                    opacity: apple === 0 ? 0.7 : 1,
                    transition: "background 0.1s, opacity 0.2s",
                  }}
                  onMouseDown={() => !gameOver && handleMouseDown(rowIdx, colIdx)}
                  onMouseEnter={() => !gameOver && handleMouseEnter(rowIdx, colIdx)}
                  onMouseUp={!gameOver ? handleMouseUp : undefined}
                >
                  {apple !== 0 ? apple : ""}
                </div>
              ))}
            </div>
          ))}
        </div>
        <div style={{ marginLeft: 30, display: "flex", flexDirection: "column", gap: 10 }}>
          <div style={{ fontWeight: "bold", marginBottom: 8 }}>사과 개수 조절</div>
          <div>
            <span>행: </span>
            <button onClick={() => handleResize(Math.max(3, rows - 1), cols)} disabled={gameOver}>-</button>
            <span style={{ margin: "0 8px" }}>{rows}</span>
            <button onClick={() => handleResize(Math.min(20, rows + 1), cols)} disabled={gameOver}>+</button>
          </div>
          <div>
            <span>열: </span>
            <button onClick={() => handleResize(rows, Math.max(3, cols - 1))} disabled={gameOver}>-</button>
            <span style={{ margin: "0 8px" }}>{cols}</span>
            <button onClick={() => handleResize(rows, Math.min(20, cols + 1))} disabled={gameOver}>+</button>
          </div>
          <div style={{ marginTop: 16 }}>
            <span>타이머(초): </span>
            <input
              type="number"
              min={5}
              max={600}
              value={customTime}
              onChange={handleTimeChange}
              disabled={gameOver}
              style={{ width: 60, textAlign: "right" }}
            />
          </div>
        </div>

        <div style={{ marginTop: 32, textAlign: "center", 
        position: "fixed",
        left: 0,
        bottom: 0,
        width: "100%", }} ref={scriptElement}>
          <ins
            className="kakao_ad_area"
            style={{ display: "none" }}
            data-ad-unit="DAN-hsPJu5SU6nUfFFLZ"
            data-ad-width="320"
            data-ad-height="50"
          ></ins>
        </div>
      </div>
    </>
  );
};

export default AppleBoard;
